"""Execution-verified text-to-SQL harness.

Contract (fixed): solve(task, env) -> {"sql": str}
  task  {"id", "db_id", "question", "hint"}
  env.chat(messages, max_tokens=None) -> str     capped per task: env.max_calls
  env.schema(db_id) -> str
  env.execute(sql, max_rows=20) -> dict          {ok, columns, rows, n_rows, error}
  env.descriptions(db_id) -> str
  env.prompt(name) -> str
  env.config -> dict

Strategy: one drafting call, then execute the draft. If it errors, returns no
rows, or its projection looks ambiguous for the question, spend the remaining
call on a repair message that includes the observed result and the real stored
values for the literals used in the query.
"""

import re

SQL_BLOCK = re.compile(r"```(?:sql|sqlite)?\s*(.*?)```", re.S | re.I)
CREATE_RE = re.compile(
    r"CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?[\"'`\[]?([A-Za-z_][\w$]*)[\"'`\]]?\s*\((.*?)\)\s*;",
    re.S | re.I,
)
COL_RE = re.compile(r"^\s*[\"'`\[]?([A-Za-z_][\w$]*)[\"'`\]]?\s+([A-Za-z]+)")
SKIP_COL = {"primary", "foreign", "unique", "check", "constraint", "key"}
TEXT_TYPES = ("char", "text", "clob")
LIT_RE = re.compile(r"'((?:[^']|'')*)'")
STOPWORDS = {
    "select", "from", "where", "and", "or", "not", "in", "like", "join", "on",
    "as", "group", "by", "order", "limit", "having", "distinct", "asc", "desc",
    "left", "inner", "outer", "union", "all", "count", "sum", "avg", "min", "max",
    "case", "when", "then", "else", "end", "null", "is", "between", "exists",
}


def extract_sql(text):
    blocks = [b.strip() for b in SQL_BLOCK.findall(text or "") if b.strip()]
    if blocks:
        return blocks[-1].rstrip(";").strip()
    t = (text or "").strip()
    m = re.search(r"(?is)\b(select|with)\b.*", t)
    if m:
        return m.group(0).rstrip(";").strip()
    return t.rstrip(";").strip()


def _tables(schema):
    """[(table_name, [(col, type), ...]), ...] in schema order."""
    out = []
    for name, body in CREATE_RE.findall(schema or ""):
        cols = []
        depth = 0
        cur = ""
        parts = []
        for ch in body:
            if ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur)
                cur = ""
            else:
                cur += ch
        parts.append(cur)
        for p in parts:
            m = COL_RE.match(p)
            if not m:
                continue
            col, typ = m.group(1), m.group(2).lower()
            if col.lower() in SKIP_COL:
                continue
            cols.append((col, typ))
        out.append((name, cols))
    return out


def _aliases(sql, tables):
    """Map alias/table token -> real table name (best effort)."""
    names = {t.lower(): t for t, _ in tables}
    amap = {}
    for m in re.finditer(r"(?is)\b(?:from|join)\s+[\"'`\[]?([A-Za-z_][\w$]*)[\"'`\]]?"
                         r"(?:\s+(?:as\s+)?([A-Za-z_][\w$]*))?", sql):
        tbl, alias = m.group(1), m.group(2)
        real = names.get(tbl.lower())
        if not real:
            continue
        amap[real.lower()] = real
        if alias and alias.lower() not in STOPWORDS:
            amap[alias.lower()] = real
    return amap


def _probe_literals(sql, schema, env, limit):
    """For each quoted literal, show real stored values that resemble it."""
    tables = _tables(schema)
    if not tables:
        return []
    amap = _aliases(sql, tables)
    cols_by_table = {t.lower(): cols for t, cols in tables}
    lits = []
    for raw in LIT_RE.findall(sql):
        v = raw.replace("''", "'").strip().strip("%").strip()
        if len(v) < 3 or v.isdigit():
            continue
        if v not in lits:
            lits.append(v)
    notes = []
    for v in lits[:limit]:
        core = re.sub(r"[^A-Za-z0-9 ]", " ", v).split()
        core = [w for w in core if len(w) >= 3]
        if not core:
            continue
        key = max(core, key=len)
        targets = []
        # qualified references first: alias.col / table.col
        for m in re.finditer(r"([A-Za-z_][\w$]*)\.([A-Za-z_][\w$]*)", sql):
            tbl = amap.get(m.group(1).lower())
            if not tbl:
                continue
            for c, typ in cols_by_table.get(tbl.lower(), []):
                if c.lower() == m.group(2).lower() and any(k in typ for k in TEXT_TYPES):
                    targets.append((tbl, c))
        if not targets:
            for tbl, cols in tables:
                for c, typ in cols:
                    if any(k in typ for k in TEXT_TYPES):
                        targets.append((tbl, c))
        seen = set()
        for tbl, c in targets:
            if (tbl, c) in seen:
                continue
            seen.add((tbl, c))
            q = ('SELECT DISTINCT "%s" FROM "%s" WHERE "%s" LIKE \'%%%s%%\' LIMIT 6'
                 % (c, tbl, c, key.replace("'", "''")))
            try:
                r = env.execute(q, max_rows=6)
            except Exception:
                continue
            if not r.get("ok") or not r.get("rows"):
                continue
            vals = [row[0] for row in r["rows"]]
            notes.append("Literal %r -> actual stored values in %s.%s: %s"
                         % (v, tbl, c, json_like(vals)))
            break
        if len(notes) >= limit:
            break
    return notes


def json_like(vals):
    return "[" + ", ".join(repr(v) for v in vals) + "]"


def _shape_doubt(question, sql):
    q = (question or "").lower()
    s = (sql or "").lower()
    asks_all = bool(re.search(r"\bdetails?\b|\ball (?:the )?(?:information|info|data)\b"
                              r"|\beverything\b|\bfull record", q))
    star = "*" in s
    if asks_all and not star:
        return ("The question asks for details/full information, but the query selects only "
                "some columns. Such questions usually expect every column of the relevant "
                "table(s) (SELECT T1.* or SELECT * for the joined rows).")
    if not asks_all and star and re.search(r"\bwhich\b|\bwhat\b", q):
        return ("The query uses SELECT * although the question may name specific attributes; "
                "keep * only if the question asks for whole records/details, otherwise select "
                "exactly the requested attributes.")
    return ""


def solve(task, env):
    cfg = env.config or {}
    schema = env.schema(task["db_id"])
    user = "Database: %s\n\nSchema:\n%s\n" % (task["db_id"], schema)
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc.strip():
        user += "\nColumn descriptions:\n%s\n" % desc.strip()[:4000]
    user += "\nQuestion: %s" % task["question"]
    if task.get("hint"):
        user += "\nHint: %s" % task["hint"]
    messages = [{"role": "system", "content": env.prompt("system_prompt.md")},
                {"role": "user", "content": user}]
    reply = env.chat(messages, max_tokens=cfg.get("max_tokens", 1400))
    sql = extract_sql(reply)
    if not cfg.get("verify", True):
        return {"sql": sql}

    try:
        res = env.execute(sql, max_rows=8)
    except Exception:
        res = {"ok": False, "error": "execution unavailable"}
    if not res.get("ok") and "unavailable" in str(res.get("error", "")):
        return {"sql": sql}

    problem = ""
    if not res.get("ok"):
        problem = "The query FAILED: %s" % res.get("error")
    elif not res.get("rows"):
        problem = ("The query executed but returned ZERO rows. Most likely a literal does not "
                   "match the stored text (case, spacing, abbreviation), a join key is wrong, "
                   "or a filter is too strict. Loosen string matching with LIKE '%...%' on the "
                   "distinctive words, and re-check joins/filters.")
    else:
        problem = _shape_doubt(task["question"], sql)
    if not problem:
        return {"sql": sql}

    feedback = [problem]
    if res.get("ok"):
        feedback.append("Current result: %d row(s), columns %s, first rows %s"
                        % (res.get("n_rows", 0), res.get("columns"), res.get("rows")[:3]))
    try:
        notes = _probe_literals(sql, schema, env, int(cfg.get("max_probe_literals", 4)))
    except Exception:
        notes = []
    feedback.extend(notes)
    feedback.append("Revise the query so its result matches the question exactly (right columns, "
                    "right rows). Reply with the corrected query in a single ```sql block.")
    messages = messages + [{"role": "assistant", "content": reply},
                           {"role": "user", "content": "\n".join(feedback)}]
    try:
        reply2 = env.chat(messages, max_tokens=cfg.get("max_tokens", 1400))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    try:
        res2 = env.execute(sql2, max_rows=8)
    except Exception:
        return {"sql": sql}
    if not res2.get("ok"):
        return {"sql": sql}
    if not res2.get("rows") and res.get("rows"):
        return {"sql": sql}
    return {"sql": sql2}

